/**
 * France (metropolitan + Corsica) areas: a verbatim copy of the backend's client
 * dataset (backend-protest-base docs/plans/france/fr-areas-client.v1.json,
 * sha256 b444b4d61a383dab…). The backend built it from the same
 * snapshot as its area tokens, so on-device matching agrees with its `areas` filter.
 * Do not edit by hand: regenerate with local/tools/generate-fr-postal-data.mjs.
 */

export interface FranceRegion {
  /** Area token, r:fr:<slug>. */
  token: string;
  /** INSEE région code. */
  code: string;
  /** Official name, e.g. "Île-de-France". */
  name: string;
  /** [lng, lat]: the population-weighted mean of its communes. */
  center: [number, number];
}

export interface FranceDepartement {
  /** Area token, p:fr:<code in lower case>. */
  token: string;
  /** INSEE code, e.g. "75" or "2A". */
  code: string;
  name: string;
  /** Token of its région. */
  region: string;
  /** [lng, lat]: the population-weighted mean of its communes. */
  center: [number, number];
}

/** A commune using a postcode: [name, INSEE code, département code]. */
export type FranceCommune = [name: string, insee: string, departement: string];

export interface FranceAreas {
  version: number;
  generated: string;
  note: string;
  regions: FranceRegion[];
  departements: FranceDepartement[];
  /** 5-digit postcode, a string ("01000"), → its communes, most populous first. */
  postcodes: Record<string, FranceCommune[]>;
}

